import http from 'node:http';
import { readFile, mkdir, writeFile, rename } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

const root = path.dirname(fileURLToPath(import.meta.url));
const defaultBooksFile = path.join(root, 'data', 'books.json');
const defaultPublicDir = path.join(root, 'public');

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

function json(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  response.end(JSON.stringify(value));
}

async function readBody(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 1_000_000) throw new HttpError(413, 'Request is too large.');
  }
  try {
    return JSON.parse(body);
  } catch {
    throw new HttpError(400, 'Please send valid JSON.');
  }
}

function textField(value, name, max, required = false) {
  if (value === undefined && !required) return '';
  if (typeof value !== 'string') throw new HttpError(400, `${name} must be text.`);
  const text = value.trim();
  if (required && !text) throw new HttpError(400, `${name} is required.`);
  if (text.length > max) throw new HttpError(400, `${name} must be ${max} characters or fewer.`);
  return text;
}

export function createServer({ booksFile = defaultBooksFile, publicDir = defaultPublicDir } = {}) {
  // Serialize changes so two near-simultaneous requests cannot overwrite one another.
  let pending = Promise.resolve();

  async function loadBooks() {
    try {
      const books = JSON.parse(await readFile(booksFile, 'utf8'));
      if (!Array.isArray(books)) throw new Error('Book data is not an array.');
      return books;
    } catch (error) {
      if (error.code === 'ENOENT') return [];
      throw error;
    }
  }

  async function saveBooks(books) {
    await mkdir(path.dirname(booksFile), { recursive: true });
    const temporaryFile = `${booksFile}.${randomUUID()}.tmp`;
    await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
    await rename(temporaryFile, booksFile);
  }

  function mutate(change) {
    const result = pending.then(async () => {
      const books = await loadBooks();
      const value = await change(books);
      await saveBooks(books);
      return value;
    });
    pending = result.catch(() => {});
    return result;
  }

  return http.createServer(async (request, response) => {
    try {
      const pathname = new URL(request.url, 'http://localhost').pathname;
      const { method } = request;

      if (pathname === '/api/books' && method === 'GET') {
        return json(response, 200, await loadBooks());
      }
      if (pathname === '/api/books' && method === 'POST') {
        const input = await readBody(request);
        if (!input || typeof input !== 'object' || Array.isArray(input)) throw new HttpError(400, 'Please enter a book.');
        const title = textField(input.title, 'Title', 200, true);
        const author = textField(input.author, 'Author', 150, true);
        const notes = textField(input.notes, 'Notes', 10000);
        const status = input.status ?? 'reading';
        if (!['reading', 'finished'].includes(status)) throw new HttpError(400, 'Invalid reading status.');
        const book = {
          id: randomUUID(), title, author, notes, status,
          createdAt: new Date().toISOString(),
          finishedAt: status === 'finished' ? new Date().toISOString() : null
        };
        await mutate(books => { books.unshift(book); });
        return json(response, 201, book);
      }

      const bookMatch = pathname.match(/^\/api\/books\/([0-9a-f-]{36})$/i);
      if (bookMatch && method === 'GET') {
        const book = (await loadBooks()).find(item => item.id === bookMatch[1]);
        if (!book) throw new HttpError(404, 'Book not found.');
        return json(response, 200, book);
      }
      if (bookMatch && method === 'PATCH') {
        const input = await readBody(request);
        if (!input || typeof input !== 'object' || Array.isArray(input)) throw new HttpError(400, 'Please enter a change.');
        if (!Object.keys(input).length || Object.keys(input).some(key => !['status', 'notes'].includes(key))) {
          throw new HttpError(400, 'Only status and notes can be changed.');
        }
        const notes = input.notes === undefined ? undefined : textField(input.notes, 'Notes', 10000);
        if (input.status !== undefined && !['reading', 'finished'].includes(input.status)) {
          throw new HttpError(400, 'Invalid reading status.');
        }
        const book = await mutate(books => {
          const item = books.find(entry => entry.id === bookMatch[1]);
          if (!item) throw new HttpError(404, 'Book not found.');
          if (notes !== undefined) item.notes = notes;
          if (input.status !== undefined) {
            item.status = input.status;
            item.finishedAt = input.status === 'finished' ? new Date().toISOString() : null;
          }
          return item;
        });
        return json(response, 200, book);
      }
      if (bookMatch && method === 'DELETE') {
        await mutate(books => {
          const index = books.findIndex(item => item.id === bookMatch[1]);
          if (index === -1) throw new HttpError(404, 'Book not found.');
          books.splice(index, 1);
        });
        return json(response, 200, { ok: true });
      }
      if (pathname.startsWith('/api/')) throw new HttpError(404, 'Not found.');

      const assets = {
        '/styles.css': ['styles.css', 'text/css; charset=utf-8'],
        '/app.js': ['app.js', 'text/javascript; charset=utf-8'],
        '/favicon.svg': ['favicon.svg', 'image/svg+xml']
      };
      const asset = assets[pathname];
      if (method === 'GET' && (asset || pathname === '/' || /^\/books\/[0-9a-f-]{36}$/i.test(pathname))) {
        const [file, type] = asset ?? ['index.html', 'text/html; charset=utf-8'];
        response.writeHead(200, { 'Content-Type': type });
        response.end(await readFile(path.join(publicDir, file)));
        return;
      }
      throw new HttpError(404, 'Not found.');
    } catch (error) {
      if (!error.status) console.error(error);
      if (!response.headersSent) json(response, error.status ?? 500, { error: error.status ? error.message : 'Something went wrong on the server.' });
    }
  });
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT) || 3000;
  createServer({ booksFile: process.env.BOOKS_FILE || defaultBooksFile }).listen(port, '0.0.0.0', () => {
    console.log(`Reading Room is open at http://localhost:${port}`);
  });
}

