const app = document.querySelector('#app');
const addDialog = document.querySelector('#add-dialog');
const notesDialog = document.querySelector('#notes-dialog');
const toast = document.querySelector('#toast');
let activeBook = null;
let toastTimer;

const arrowIcon = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>';

function notify(message) {
  toast.textContent = message;
  toast.classList.add('visible');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('visible'), 3500);
}

async function request(url, options) {
  const response = await fetch(url, options);
  let data;
  try { data = await response.json(); } catch { throw new Error('Could not read the server response.'); }
  if (!response.ok) throw new Error(data.error || 'Something went wrong. Please try again.');
  return data;
}

function dateLabel(date) {
  if (!date) return '';
  return new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(date));
}

function coverClass(book) {
  let hash = 0;
  for (const letter of book.title) hash = ((hash * 31) + letter.charCodeAt(0)) | 0;
  return `palette-${Math.abs(hash) % 6}`;
}

function makeCover(book, extraClass = '') {
  const cover = document.createElement('div');
  cover.className = `book-cover ${coverClass(book)} ${extraClass}`;
  cover.setAttribute('aria-hidden', 'true');
  cover.innerHTML = '<div class="cover-top">READING ROOM<br>EDITION</div><div class="cover-art"><span class="cover-sun"></span><span class="cover-hill cover-hill-one"></span><span class="cover-hill cover-hill-two"></span></div><div class="cover-bottom"><strong></strong><span></span></div>';
  cover.querySelector('strong').textContent = book.title;
  cover.querySelector('.cover-bottom span').textContent = book.author;
  return cover;
}

function setNavigation(section) {
  for (const name of ['home', 'reading', 'finished']) {
    document.querySelector(`#nav-${name}`).classList.toggle('active', name === section);
  }
}

function sectionHeading(kicker, title, count) {
  const heading = document.createElement('div');
  heading.className = 'section-heading';
  heading.innerHTML = '<div><span class="eyebrow"></span><h2></h2></div><span class="section-count"></span>';
  heading.querySelector('.eyebrow').textContent = kicker;
  heading.querySelector('h2').textContent = title;
  heading.querySelector('.section-count').textContent = `${count.toString().padStart(2, '0')} BOOK${count === 1 ? '' : 'S'}`;
  return heading;
}

function bookCard(book, finished = false) {
  const link = document.createElement('a');
  link.href = `/books/${book.id}`;
  link.className = `book-card ${finished ? 'finished-card' : ''}`;
  const cover = makeCover(book);
  link.append(cover);
  const body = document.createElement('div');
  body.className = 'card-body';
  body.innerHTML = '<span class="card-status"><span class="status-dot"></span><span class="status-text"></span></span><h3></h3><p class="card-author"></p><p class="card-note"></p><div class="card-bottom"><span></span><span class="card-arrow" aria-hidden="true">↗</span></div>';
  body.querySelector('.status-text').textContent = finished ? 'FINISHED' : 'CURRENTLY READING';
  body.querySelector('h3').textContent = book.title;
  body.querySelector('.card-author').textContent = `by ${book.author}`;
  body.querySelector('.card-note').textContent = book.notes || (finished ? 'A story for the shelf.' : 'Every page is a new beginning.');
  body.querySelector('.card-bottom span').textContent = finished ? `Finished ${dateLabel(book.finishedAt || book.createdAt)}` : `Added ${dateLabel(book.createdAt)}`;
  link.append(body);
  return link;
}

function emptyReading() {
  const panel = document.createElement('div');
  panel.className = 'empty-reading';
  panel.innerHTML = '<div class="empty-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-book art-book-back"><span></span></div><div class="art-book art-book-front"><span></span><i></i></div><div class="art-spark art-spark-one">✳</div><div class="art-spark art-spark-two">✦</div></div><div class="empty-copy"><span class="eyebrow">A FRESH PAGE</span><h3>Your next great read<br>starts here.</h3><p>Your shelf is waiting. Add the book you’re reading and keep a little space for the thoughts it leaves behind.</p><button class="button button-dark" type="button"><span class="button-plus">+</span> Add your first book</button></div>';
  panel.querySelector('button').addEventListener('click', openAdd);
  return panel;
}

function renderDashboard(books) {
  activeBook = null;
  document.title = 'Reading Room — Your personal book shelf';
  document.querySelector('#breadcrumb-current').textContent = 'Overview';
  setNavigation(location.hash === '#reading' ? 'reading' : location.hash === '#finished' ? 'finished' : 'home');
  const reading = books.filter(book => book.status === 'reading');
  const finished = books.filter(book => book.status === 'finished');
  app.innerHTML = `
    <div class="page-intro"><div><span class="eyebrow"><span class="tiny-star">✳</span> YOUR PERSONAL LIBRARY</span><h1>A home for all<br>your stories<span class="title-period">.</span></h1><p>A quiet little place to keep the books you’re reading, the ones you’ve loved, and everything in between.</p></div><div class="intro-decoration" aria-hidden="true"><div class="deco-circle"></div><div class="deco-book deco-book-one"></div><div class="deco-book deco-book-two"></div><div class="deco-book deco-book-three"></div><span class="deco-spark">✳</span></div></div>
    <div class="overview-strip"><div class="overview-label"><span class="overview-icon">✳</span><span>YOUR READING<br>AT A GLANCE</span></div><div class="overview-stat"><strong id="reading-count"></strong><span>Currently reading</span></div><div class="overview-stat"><strong id="finished-count"></strong><span>Books finished</span></div><div class="overview-end">ONE PAGE<br>AT A TIME <span>↗</span></div></div>
    <section id="reading" class="book-section"></section><section id="finished" class="book-section finished-section"></section>`;
  app.querySelector('#reading-count').textContent = reading.length;
  app.querySelector('#finished-count').textContent = finished.length;
  const readingSection = app.querySelector('#reading');
  readingSection.append(sectionHeading('ON YOUR NIGHTSTAND', 'Currently reading', reading.length));
  if (reading.length) {
    const grid = document.createElement('div');
    grid.className = 'book-grid';
    reading.forEach(book => grid.append(bookCard(book)));
    readingSection.append(grid);
  } else readingSection.append(emptyReading());

  const finishedSection = app.querySelector('#finished');
  finishedSection.append(sectionHeading('THE STORIES THAT STAY', 'The finished shelf', finished.length));
  if (finished.length) {
    const grid = document.createElement('div');
    grid.className = 'book-grid';
    finished.forEach(book => grid.append(bookCard(book, true)));
    finishedSection.append(grid);
  } else {
    const empty = document.createElement('div');
    empty.className = 'empty-finished';
    empty.innerHTML = '<div class="finished-empty-icon" aria-hidden="true">✓</div><div><h3>Nothing on this shelf yet</h3><p>When you finish a book, it will find a home here.</p></div><span class="empty-finished-star" aria-hidden="true">✳</span>';
    finishedSection.append(empty);
  }
  if (location.hash) requestAnimationFrame(() => document.querySelector(location.hash)?.scrollIntoView({ behavior: 'smooth' }));
}

function renderDetail(book) {
  activeBook = book;
  document.title = `${book.title} — Reading Room`;
  document.querySelector('#breadcrumb-current').textContent = book.title;
  setNavigation('home');
  app.innerHTML = `<div class="detail-page"><a href="/" class="back-link">← <span>Back to library</span></a><div class="detail-layout"><div class="detail-cover-area"><div class="detail-cover-frame"></div><div id="detail-cover"></div><div class="cover-caption">A STORY WORTH KEEPING <span>✳</span></div></div><div class="detail-content"><span class="detail-kicker"><span class="status-dot"></span><span id="detail-status"></span></span><h1 id="detail-title"></h1><p class="detail-author">by <span id="detail-author"></span></p><div class="detail-rule"></div><div class="detail-meta"><div><span>ADDED TO SHELF</span><strong id="detail-added"></strong></div><div><span>READING STATUS</span><strong id="detail-state"></strong></div></div><div class="detail-actions"><button class="button button-dark" id="status-button" type="button"></button><button class="button button-outline" id="share-button" type="button"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M9 12h6m-7.5 3.5H6a4 4 0 0 1 0-8h3m6 0h3a4 4 0 0 1 0 8h-3" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg> Copy link</button></div></div></div><section class="notes-section"><div class="notes-heading"><div><span class="eyebrow">IN THE MARGINS</span><h2>My notes<span class="title-period">.</span></h2></div><button class="text-button" id="edit-notes-button" type="button">Edit notes <span aria-hidden="true">↗</span></button></div><div class="notes-paper"><span class="notes-quote" aria-hidden="true">“</span><p id="detail-notes"></p></div></section><div class="detail-footer"><a href="/" class="back-link">← <span>All books</span></a><button class="delete-button" id="delete-button" type="button">Remove from shelf</button></div></div>`;
  app.querySelector('#detail-cover').append(makeCover(book, 'book-cover-large'));
  app.querySelector('#detail-title').textContent = book.title;
  app.querySelector('#detail-author').textContent = book.author;
  app.querySelector('#detail-status').textContent = book.status === 'finished' ? 'FINISHED BOOK' : 'CURRENTLY READING';
  app.querySelector('#detail-added').textContent = dateLabel(book.createdAt);
  app.querySelector('#detail-state').textContent = book.status === 'finished' ? 'Finished' : 'In progress';
  app.querySelector('#detail-notes').textContent = book.notes || 'No notes yet. A blank page for the thoughts you want to keep.';
  if (!book.notes) app.querySelector('#detail-notes').classList.add('notes-placeholder');
  const statusButton = app.querySelector('#status-button');
  statusButton.textContent = book.status === 'finished' ? '↶  Mark as reading' : '✓  Mark as finished';
  statusButton.addEventListener('click', async () => {
    statusButton.disabled = true;
    try {
      const updated = await request(`/api/books/${book.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: book.status === 'finished' ? 'reading' : 'finished' }) });
      renderDetail(updated);
      notify(updated.status === 'finished' ? 'Moved to your finished shelf.' : 'Back on your reading shelf.');
    } catch (error) { statusButton.disabled = false; notify(error.message); }
  });
  app.querySelector('#edit-notes-button').addEventListener('click', () => {
    document.querySelector('#edit-notes').value = book.notes;
    document.querySelector('#notes-error').hidden = true;
    notesDialog.showModal();
  });
  app.querySelector('#share-button').addEventListener('click', async () => {
    const link = `${location.origin}/books/${book.id}`;
    try {
      await navigator.clipboard.writeText(link);
      notify('Link copied to clipboard.');
    } catch {
      // Clipboard access can be unavailable outside localhost or a secure context.
      window.prompt('Copy this link to share the book:', link);
    }
  });
  app.querySelector('#delete-button').addEventListener('click', async () => {
    if (!window.confirm(`Remove “${book.title}” from your shelf? This cannot be undone.`)) return;
    try {
      await request(`/api/books/${book.id}`, { method: 'DELETE' });
      history.pushState(null, '', '/');
      await render();
      notify('Book removed from your shelf.');
    } catch (error) { notify(error.message); }
