@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Serif+Display:ital@0;1&display=swap');

:root{--paper:#f8f8f4;--white:#fff;--ink:#20342f;--muted:#7c8981;--line:#e5e9e2;--forest:#18352f;--orange:#c67b5b;--sage:#e9eee6;--serif:'DM Serif Display',Georgia,serif;--sans:'DM Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;font-family:var(--sans);color:var(--ink);background:var(--paper);font-synthesis:none}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-width:320px}button,input,textarea,select{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}svg{display:block;width:20px;height:20px}::selection{background:#dce9d9;color:var(--forest)}:focus-visible{outline:3px solid #d49a7c;outline-offset:3px}
.app-shell{min-height:100vh;display:flex}.sidebar{width:252px;flex:0 0 252px;background:#17352f;color:#fff;display:flex;flex-direction:column;padding:37px 18px 24px;min-height:100vh;position:sticky;top:0;height:100vh}.brand{display:flex;align-items:center;gap:12px;margin:0 10px 70px}.brand-mark{width:38px;height:38px;border:1px solid #9aafa2;border-radius:12px;display:grid;place-items:center;color:#e9f1e7}.brand-mark svg{width:25px;height:25px}.brand-name{font-family:var(--serif);font-size:22px;letter-spacing:-.7px;line-height:1}.brand-name>span{color:#b5ceba}.brand-name small{display:block;margin-top:8px;font:600 8px/1 var(--sans);letter-spacing:2px;color:#afc2b5}.nav-label{font-size:10px;letter-spacing:2px;font-weight:700;color:#91a99b;margin:0 18px 15px}.side-nav{display:grid;gap:5px}.nav-item{display:flex;align-items:center;gap:14px;padding:13px 16px;border-radius:9px;font-size:13px;font-weight:500;color:#b6c8bd;transition:background .18s,color .18s}.nav-item:hover,.nav-item.active{background:#2b4b41;color:#fff}.nav-item.active{font-weight:700}.nav-item svg{width:18px;height:18px;flex:none}.sidebar-bottom{margin-top:auto;padding:0 14px}.sidebar-illustration{height:85px;display:flex;align-items:flex-end;gap:5px;padding-left:18px;margin-bottom:25px;border-bottom:1px solid #4c695d}.sidebar-illustration span{width:27px;border-radius:2px 2px 0 0;border:1px solid rgba(255,255,255,.25);box-shadow:inset 4px 0 rgba(255,255,255,.09)}.sidebar-illustration span:nth-child(1){height:53px;background:#72907b;transform:rotate(-10deg) translateY(1px)}.sidebar-illustration span:nth-child(2){height:69px;background:#bca986}.sidebar-illustration span:nth-child(3){height:57px;background:#d18b6e}.sidebar-illustration span:nth-child(4){height:76px;background:#627c71;transform:rotate(9deg) translateY(1px)}.sidebar-bottom p{font:italic 18px/1.3 var(--serif);color:#e6ebdf;margin:0 0 10px}.quote-credit{font-size:10px;color:#95ac9e;letter-spacing:.5px}.sidebar-foot{border-top:1px solid #3d59