import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { createServer } from '../server.js';

async function start(booksFile) {
  const server = createServer({ booksFile });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  return { server, base: `http://127.0.0.1:${server.address().port}` };
}

async function call(base, route, method = 'GET', body) {
  const response = await fetch(`${base}${route}`, {
    method, headers: body ? { 'Content-Type': 'application/json' } : {},
    body: body ? JSON.stringify(body) : undefined
  });
  return { status: response.status, data: await response.json() };
}

test('books can be added, viewed, updated, removed, and survive a restart', async () => {
  const directory = await mkdtemp(path.join(tmpdir(), 'reading-room-'));
  const booksFile = path.join(directory, 'books.json');
  let { server, base } = await start(booksFile);
  try {
    assert.deepEqual((await call(base, '/api/books')).data, []);
    const created = await call(base, '/api/books', 'POST', {
      title: '  A Book  ', author: ' An Author ', notes: ' A thought ', status: 'reading'
    });
    assert.equal(created.status, 201);
    const book = created.data;
    assert.equal(book.title, 'A Book');
    assert.equal(book.author, 'An Author');
    assert.equal(book.notes, 'A thought');
    assert.equal(book.status, 'reading');
    assert.equal((await call(base, `/api/books/${book.id}`)).data.title, 'A Book');
    assert.equal((await fetch(`${base}/books/${book.id}`)).status, 200);

    const finished = await call(base, `/api/books/${book.id}`, 'PATCH', { status: 'finished', notes: 'Loved it.' });
    assert.equal(finished.data.status, 'finished');
    assert.ok(finished.data.finishedAt);
    assert.equal(finished.data.notes, 'Loved it.');
    assert.equal(JSON.parse(await readFile(booksFile, 'utf8'))[0].status, 'finished');

    await new Promise(resolve => server.close(resolve));
    ({ server, base } = await start(booksFile));
    assert.equal((await call(base, '/api/books')).data[0].notes, 'Loved it.');
    const reading = await call(base, `/api/books/${book.id}`, 'PATCH', { status: 'reading' });
    assert.equal(reading.data.finishedAt, null);
    assert.equal((await call(base, `/api/books/${book.id}`, 'DELETE')).status, 200);
    assert.deepEqual((await call(base, '/api/books')).data, []);
    assert.equal((await call(base, `/api/books/${book.id}`)).status, 404);
  } finally {
    await new Promise(resolve => server.close(resolve));
    await rm(directory, { recursive: true, force: true });
  }
});

test('invalid inputs are rejected and concurrent additions are preserved', async () => {
  const directory = await mkdtemp(path.join(tmpdir(), 'reading-room-'));
  const { server, base } = await start(path.join(directory, 'books.json'));
  try {
    assert.equal((await call(base, '/api/books', 'POST', { title: '', author: 'Someone' })).status, 400);
    assert.equal((await call(base, '/api/books', 'POST', { title: 'Title', author: 'Someone', status: 'unknown' })).status, 400);
    const requests = Array.from({ length: 8 }, (_, index) => call(base, '/api/books', 'POST', { title: `Book ${index}`, author: 'Someone' }));
    const results = await Promise.all(requests);
    assert.ok(results.every(result => result.status === 201));
    assert.equal((await call(base, '/api/books')).data.length, 8);
    assert.equal((await call(base, `/api/books/${results[0].data.id}`, 'PATCH', { title: 'Not allowed' })).status, 400);
    assert.equal((await fetch(`${base}/styles.css`)).status, 200);
  } finally {
    await new Promise(resolve => server.close(resolve));
    await rm(directory, { recursive: true, force: true });
  }
});

